    ('ConstructorBindingsV20.ascent_definition', '∀ {X : Type u_1} (r : PartialContextV15.PreorderSpec X) (S : X → Prop) (x y : { x // S x }), WellFoundedFrontierV20.Ascent r S y x ↔ r.le x.val y.val ∧ ¬r.le y.val x.val'),
